Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
(* [comment removed for export] *)
Local Ltac acc_hint ::=
  lazymatch goal with
  | |- acc_in ?R (Z_to_bv 64 (Z.shiftr ?a 3 + 2147450880), 1%nat) =>
      match goal with H : rng R (shad ?A) (nshad (?len + ?A' mod 8)) |- _ => constr_eq A A'; apply (acc_shZ R A len a H); lia end
  end.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CANSEC1. Context {rc : runConstT}.

Section C2DA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 : word).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl st off sym1 b e tb tl : Z) (sorted : list (option Z)) (js jt : list byte)
            (ncells : nat).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HTB : 1 <= tb <= 12.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Hypothesis HTL : tl - tb = 3.
  Hypothesis HBE : 0 <= b <= e /\ e <= 256.
  Hypothesis HST : 0 <= st.
